//This method is sets values for generating pallete and gets the value of color on the basis of t
vec3 getPalette(float t)
{
    return palette(
    vec3( 0.5, 0.5, 0.5	),
    vec3(0.5, 0.5, 0.5),
    vec3(2.0, 1.0, 0.0	),
    vec3(0.50, 0.20, 0.25),
    t);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord/iResolution.xy;

    vec3 col = getPalette(sin(iTime * .2));

    fragColor = vec4(col,1.0);
}

#define pi 3.1415926


//This methos is for creation of palette
vec3 palette(vec3 a , vec3 b, vec3 c , vec3 d, float t)
{
    return a + b*cos( 2.*pi*( c*t + d ));

    //a = y axis of wave
    //b = amplitude (height of wave)
    //c = frequency
    //d = (phase / 2*pi)

}
